import Foundation

/// The sentence each recorded clip says, with numbers spelled out. Generated by
/// `scripts/voice-prompts/generate.py --export-text`; Kokoro renders from it.
enum PromptText {
    private static let sentences: [String: String] = load(.main)

    static func sentence(for key: String) -> String? { sentences[key] }

    static var allKeys: Set<String> { Set(sentences.keys) }

    static func load(_ bundle: Bundle) -> [String: String] {
        guard let url = bundle.url(forResource: "PromptText", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode([String: String].self, from: data) else { return [:] }
        return decoded
    }
}
